// GET ?e_sorder_id=S2737684 or S2737684.0001. The change log is read for
// the whole order (every generation); each entry lists its generations.
const q = $input.first().json.query || {};
const m = String(q.e_sorder_id || '').trim().toUpperCase().match(/^S?(\d+)(?:\.(\d{1,4}))?$/);
if (!m) return [{ json: { ok: false, statusCode: 400, body: { success: false, error: 'Missing or invalid e_sorder_id (expected S1234567 or S1234567.0001).', step: 'validate' } } }];
return [{ json: { ok: true, oid: 'S' + m[1] } }];

// Eclipse answers { comments: [{ generationIds: ['1'] | ['ALL'], date, time,
// userId, comment }] } (per the get_sorder_history.py reference script).
// date + time are UTC; `at` is sent as ISO with a Z so the page can show it
// in the rep's own time zone. Entries keep Eclipse's order.
const v = $('Validate').first().json;
const env = $input.first().json;
if (env.error) return [{ json: { statusCode: 502, body: { success: false, step: 'getOrderChangeLog',
  error: 'Eclipse GET /SalesOrders/' + v.oid + '/OrderChangeLog failed: ' + env.error + ' ' + JSON.stringify(env.message || '').substring(0, 500) } } }];
const list = Array.isArray(env.comments) ? env.comments : (Array.isArray(env.results) && env.results[0] && Array.isArray(env.results[0].comments) ? env.results[0].comments : []);
const iso = (d, t) => {
  if (!d) return '';
  let s = String(d).slice(0, 10) + 'T' + String(t || '00:00:00');
  if (!/(Z|[+-]\d{2}:?\d{2})$/.test(s)) s += 'Z';
  return s;
};
const entries = list.map((c) => ({
  gens: (Array.isArray(c.generationIds) ? c.generationIds : [c.generationIds]).filter((g) => g != null && g !== '').map(String),
  at: iso(c.date, c.time),
  date: c.date || '', time: c.time || '',
  user: c.userId || '',
  comment: String(c.comment || ''),
}));
return [{ json: { statusCode: 200, body: { success: true, order_id: v.oid, entries } } }];
